/* Arabic interface text — EGYPTIAN Arabic (العامية المصرية), chosen by Ali on 18 Oct 2026 (choice 5B; it replaced the simple
   Modern Standard Arabic of 4 Oct — the old file is in git history before v6.36).
   Key = the exact English text passed to tr(). Keep {placeholders} intact.
   Style: short Egyptian buttons (احفظ، نزّل، افتح، امسح، كمّل); instructions «دوس على…»، «اختار»; progress «بيحمّل…»، «بيدوّر…»;
   everyday words (مفيش، لسه، دلوقتي، النهارده، عشان، كام، إزاي); app sections in «quotes» (المحرك، عقلي، الفلوس، الشات).
   Brand and model names (Attune, Qwen, ChatGPT…) stay in Latin letters.
   Examples of what people TYPE may stay in Egyptian Arabic (that is how they write). */
