  "Every area you look at is kept, so it works again with no signal. You can also download an area before you travel. Place search needs a connection; your own saved places are searchable without one.": "كل منطقة بتتفرج عليها بتتحفظ، فتشتغل تاني من غير نت. وتقدر كمان تنزّل منطقة قبل ما تسافر. البحث عن الأماكن محتاج نت؛ أماكنك المحفوظة تقدر تدوّر فيها من غيره.",
  "offline — showing saved tiles": "من غير نت — بنعرض الخريطة المحفوظة",
  "Search a place — مدينة نصر، القاهرة": "دوّر على مكان — مدينة نصر، القاهرة",
  "Search your saved places": "دوّر في أماكنك المحفوظة",
