  "Choose a file": "اختار ملف",
  "Translate…": "ترجم…",
  "Translating into {l} — part {n} of {t}…": "بيترجم لـ {l} — الجزء {n} من {t}…",
  "{n} piece(s) couldn't be translated and were left as they were.": "{n} جزء مقدرناش نترجمه، فسبناه زي ما هو.",
  "Translated by the AI on your phone — check important names and numbers.": "اترجم بالذكاء الاصطناعي على موبايلك — راجع الأسامي والأرقام المهمة.",
  "Translating needs an AI model — open Engine and install one.": "الترجمة محتاجة نموذج ذكاء اصطناعي — افتح «المحرك» ونزّل واحد.",
  "The AI on your phone translates it piece by piece; headings, lists, tables and numbers stay in place. Long files take a few minutes.": "الذكاء الاصطناعي على موبايلك بيترجم الملف حتة حتة؛ والعناوين والقوايم والجداول والأرقام بتفضل في مكانها. الملفات الطويلة بتاخد كام دقيقة.",
  "Spanish": "الإسباني",
  "Unlimited video downloads in the quality you choose": "نزّل فيديوهات من غير حد وبالجودة اللي تختارها",
  "Video Downloader": "تنزيل الفيديوهات",
  "Paste a video link, pick the quality, save it to your phone": "الزق لينك الفيديو، اختار الجودة، واحفظه على موبايلك",
  "Copy a video's link, paste it here, pick the quality — it's saved to your phone's Movies folder. Works with direct video links, Google Drive, Dropbox, archive.org, Wikimedia Commons and pages that show a plain video.": "انسخ لينك الفيديو، والزقه هنا، واختار الجودة — بيتحفظ في فولدر Movies على موبايلك. بيشتغل مع لينكات الفيديو المباشرة، وGoogle Drive، وDropbox، وarchive.org، وWikimedia Commons، والصفحات اللي فيها فيديو عادي.",
  "Find the video": "دوّر على الفيديو",
  "Looking for the video…": "بيدوّر على الفيديو…",
  "Choose the quality": "اختار الجودة",
  "Download": "نزّل",
  "Downloads": "التنزيلات",
  "Audio only": "الصوت بس",
  "Video": "فيديو",
  "Original": "الأصلي",
  "Play": "شغّل",
  "Waiting for the internet…": "مستني النت…",
  "Only download videos you have the right to keep.": "نزّل بس الفيديوهات اللي من حقك تحتفظ بيها.",
  "The clipboard is empty — copy the video's link first": "الحافظة فاضية — انسخ لينك الفيديو الأول",
  "Long-press the box and choose Paste": "دوس مطوّل على الخانة واختار «لصق»",
  "That isn't a link. Copy the video's link (it starts with https://) and paste it here.": "ده مش لينك. انسخ لينك الفيديو (بيبدأ بـ https://) والزقه هنا.",
  "{site} doesn't allow its videos to be downloaded, so Attune can't save them (Google Play removes apps that do). Links that work: direct video links, Google Drive, Dropbox, archive.org, Wikimedia Commons, and pages that show a plain video file.": "{site} مش بيسمح بتنزيل فيديوهاته، فـ Attune مش هيقدر يحفظها (Google Play بيشيل التطبيقات اللي بتعمل كده). اللينكات اللي بتشتغل: لينكات الفيديو المباشرة، وGoogle Drive، وDropbox، وarchive.org، وWikimedia Commons، والصفحات اللي فيها ملف فيديو عادي.",
  "a streaming service": "خدمة البث دي",
  "this site": "الموقع ده",
  "That's a live-stream link (.m3u8) — it's streamed in pieces and can't be saved as one file.": "ده لينك بث مباشر (.m3u8) — بيتبعت حتت ومينفعش يتحفظ كملف واحد.",
  "Downloading works in the Android app.": "التنزيل شغال في تطبيق أندرويد.",
  "Google Drive didn't give the file — make sure it's shared as \"Anyone with the link\".": "Google Drive مدّاش الملف — اتأكد إنه متشارك مع «أي حد معاه اللينك».",
  "This page plays a {site} video, which can't be downloaded.": "الصفحة دي بتعرض فيديو من {site}، ومينفعش يتنزّل.",
  "This page streams its video in pieces (HLS), which can't be saved as one file.": "الصفحة دي بتبث الفيديو حتت (HLS)، ومينفعش يتحفظ كملف واحد.",
  "No downloadable video was found on that page.": "ملقيناش فيديو ينفع يتنزّل في الصفحة دي.",
  "That link didn't give a video file (the site sent {t}).": "اللينك ده مرجّعش ملف فيديو (الموقع بعت {t}).",
  "No downloadable video was found there.": "ملقيناش فيديو ينفع يتنزّل هناك.",
  "Free includes 3 video downloads a day — Pro is unlimited": "المجاني فيه 3 تنزيلات فيديو في اليوم — وPro من غير حد",
  "Downloading — you can close Attune, it keeps going": "بينزّل — تقدر تقفل Attune، وهيكمّل",
  "The file was moved or deleted": "الملف اتنقل أو اتمسح",
  "The download failed — the link may have expired. Find it again and retry.": "التنزيل فشل — ممكن اللينك يكون خلص. دوّر عليه تاني وجرّب تاني.",
  "PDF, Word, PowerPoint, Excel, photos — 80+ conversions, and translation": "PDF وWord وPowerPoint وExcel والصور — أكتر من 80 تحويل، والترجمة",
  "PDF ↔ Word, PowerPoint → PDF, photos → PDF, scanned paper → editable Word, Excel ↔ CSV ↔ JSON, e-books, web pages, subtitles, merge and split PDFs — on your phone. Your files are never uploaded to a converter website.": "PDF ↔ وورد، وPowerPoint ← PDF، والصور ← PDF، والورق المتصوّر ← وورد تقدر تعدّله، وExcel ↔ CSV ↔ JSON، والكتب الإلكترونية، وصفحات الويب، وترجمات الأفلام، ودمج ملفات PDF وتقسيمها — على موبايلك. ملفاتك عمرها ما بتترفع على موقع تحويل.",
  "PDF · Word · PowerPoint · Excel · CSV · photos · e-books · web pages · subtitles — several photos → one PDF, several PDFs → merged": "PDF · وورد · باوربوينت · إكسل · CSV · صور · كتب إلكترونية · صفحات ويب · ترجمات أفلام — كذا صورة ← PDF واحد، وكذا PDF ← ملف واحد مدموج",
  "That kind of file can't be converted here yet. Try PDF, Word, PowerPoint, Excel, CSV, photos, text, e-books, web pages or subtitles.": "النوع ده من الملفات لسه مينفعش يتحوّل هنا. جرّب PDF أو وورد أو باوربوينت أو إكسل أو CSV أو صور أو نصوص أو كتب إلكترونية أو صفحات ويب أو ملفات ترجمة.",
  "Pick one file — or several photos (→ one PDF), or several PDFs (→ merged).": "اختار ملف واحد — أو كذا صورة (← PDF واحد)، أو كذا PDF (← ملف مدموج).",
