  "This PDF is locked with a password — open it, save a copy without the password, and try again.": "ملف PDF ده مقفول بباسورد — افتحه واحفظ نسخة من غير الباسورد، وجرّب تاني.",
  "That file isn't a Word / Excel file (not a zip).": "الملف ده مش ملف وورد / إكسل.",
  "That file isn't a Word document.": "الملف ده مش مستند وورد.",
  "That file isn't an Excel workbook.": "الملف ده مش ملف إكسل.",
  "Unlimited file conversions, including scanned paper → editable Word": "تحويل ملفات من غير حد، ومنها الورق المتصوّر ← وورد تقدر تعدّله",
  "Unlimited Chat X-Rays: who owes you, promises and unanswered questions in your WhatsApp chats": "فحص محادثات من غير حد: مين عليه فلوس ليك، والوعود، والأسئلة اللي محدش ردّ عليها في محادثات الواتساب",
  "Chat X-Ray": "فحص المحادثة",
  "Money, promises & questions in a WhatsApp chat": "الفلوس والوعود والأسئلة في محادثة واتساب",
  "Who owes whom, what was promised, which dates were agreed and which questions got no answer — read from a WhatsApp chat on your phone. The chat never leaves the phone.": "مين عليه لمين، إيه اللي اتوعد بيه، أنهي مواعيد اتفقتوا عليها، وأنهي أسئلة محدش ردّ عليها — من محادثة واتساب على موبايلك. المحادثة عمرها ما بتخرج من الموبايل.",
  "In WhatsApp, open the chat → ⋮ → More → Export chat → Without media.": "في الواتساب: افتح المحادثة ← ⋮ ← المزيد ← تصدير الدردشة ← بدون وسائط.",
  "Pick Attune in the share list — or save the file and choose it here.": "اختار Attune من قايمة المشاركة — أو احفظ الملف واختاره من هنا.",
  "Choose the exported chat (.txt)": "اختار المحادثة المتصدّرة (.txt)",
  "…or paste the chat text here": "…أو الزق نص المحادثة هنا",
  "Read the pasted chat": "اقرا المحادثة الملزوقة",
  "Earlier X-rays": "فحوصات قبل كده",
  "That doesn't look like an exported WhatsApp chat. In WhatsApp: open the chat → ⋮ → More → Export chat → Without media → Attune.": "ده مش شكله محادثة واتساب متصدّرة. في الواتساب: افتح المحادثة ← ⋮ ← المزيد ← تصدير الدردشة ← بدون وسائط ← Attune.",
  "Chat with {p}": "محادثة مع {p}",
