  "Before you pay or sign: paste the offer, the seller's message or an installment plan — or add a screenshot. Attune works out the real cost, checks the market price, looks for scam signs and writes your reply.": "قبل ما تدفع أو تمضي: الزق العرض أو رسالة البياع أو خطة التقسيط — أو ضيف سكرين شوت. Attune بيحسب التكلفة الحقيقية، ويقارنها بسعر السوق، ويدوّر على علامات النصب، ويكتبلك الرد.",
