  "The AI on your phone rewords — it never adds a number, date or skill you didn't write. Anything it suggests is shown first.": "الذكاء الاصطناعي على موبايلك بيعيد الصياغة بس — عمره ما بيضيف رقم أو تاريخ أو مهارة إنت مكتبتهاش. وأي اقتراح بيتعرض عليك الأول.",
