  "Your own recipes for the AI — create, import, share": "وصفاتك إنت للذكاء الاصطناعي — اعمل، استورد، شارك",
  "Your own recipes for the AI: how to write your quotes, replies, lessons. Start a message with a skill's command, or let the app pick it when your question fits. A skill adds instructions, facts and a checklist to your question; a small program inside it (only if you keep one) runs offline in a locked box.": "وصفاتك إنت للذكاء الاصطناعي: يكتب عروض أسعارك وردودك ودروسك إزاي. ابدأ رسالتك بأمر المهارة، أو سيب التطبيق يختارها لما سؤالك يناسبها. المهارة بتضيف لسؤالك تعليمات ومعلومات وقايمة مراجعة؛ ولو خليت فيها برنامج صغير، بيشتغل من غير نت جوه بيئة معزولة.",
