  "Start a message with it to use this skill, e.g. “/quote 3 birthday cakes for Friday”.": "ابدأ بيه رسالة عشان تستخدم المهارة دي، مثلًا «/quote 3 تورتات عيد ميلاد يوم الجمعة».",
  "When to use it": "تستخدمها إمتى",
  "Words that tell the app this skill fits: cake order, price offer, delivery…": "كلمات بتعرّف التطبيق إن المهارة دي مناسبة: طلب تورتة، عرض سعر، توصيل…",
  "The app uses these words to pick the skill by itself when your question fits.": "التطبيق بيستخدم الكلمات دي عشان يختار المهارة لوحده لما سؤالك يناسبها.",
  "Instructions": "التعليمات",
