  "Invoices with VAT, payments and overdue tracking, stock and purchasing, reports — your own accounting, on your phone, in English and Arabic.": "فواتير بالضريبة، وتحصيل الفلوس ومتابعة المتأخر، والمخزون والمشتريات، والتقارير — حساباتك إنت على موبايلك، بالعربي والإنجليزي.",
