  "For power users. Community models are not tested by Attune: a model bigger than about 40% of this phone's memory will run slowly and hot, or be closed by Android. Check the size on its Hugging Face page first, and prefer the Q4 file.": "للناس المحترفة. نماذج المجتمع Attune مجرّبهاش: أي نموذج أكبر من حوالي 40% من ذاكرة الموبايل هيشتغل ببطء ويسخّن الموبايل، أو أندرويد هيقفله. شوف حجمه في صفحته على Hugging Face الأول، وفضّل ملف Q4.",
