  "It answers from this device, and it can look through everything you've asked it before — so questions about your own work have real answers, not guesses.": "بيجاوب من الجهاز ده، وبيقدر يدوّر في كل اللي سألته قبل كده — فأسئلتك عن شغلك بتاخد إجابات حقيقية، مش تخمين.",
