  "Your strongest model, slow and careful": "أقوى نموذج عندك، أبطأ وأدق",
  "Wikipedia · the question leaves the device, the answer is still written here": "ويكيبيديا · السؤال بيخرج من الجهاز، والإجابة بتتكتب هنا",
  "Runs on this device · no account · works with no signal": "شغال على الجهاز ده · من غير حساب · بيشتغل من غير نت",
