  "Paste": "الصق",
  "Photo": "صورة",
  "or drag a file or some text onto this box": "أو اسحب ملف أو نص على المربع ده",
  "A photo is read word for word and the text kept, so a whiteboard, a receipt or a handwritten site note becomes searchable — and anything promised on it shows up on the right.": "الصورة بتتقري كلمة كلمة ونصها بيتحفظ، فالسبورة أو الإيصال أو ملاحظة الموقع المكتوبة بخط الإيد تبقى تقدر تدوّر فيها — وأي وعد مكتوب فيها بيظهر على اليمين.",
  "Your words": "كلماتك",
  "The words your trade uses, that a general model gets wrong every time. Teach it once and it never gets them wrong again — in answers, documents and translations alike. This is the part of the app that gets better the longer you use it, and the part nobody can copy.": "الكلمات اللي شغلك بيستخدمها، واللي النموذج العادي بيغلط فيها كل مرة. علّمهاله مرة واحدة ومش هيغلط فيها تاني — في الردود والمستندات والترجمات. ده الجزء من التطبيق اللي بيتحسّن كل ما تستخدمه، ومحدش يقدر ينسخه.",
  "the word (سطحة, mobilisation…)": "الكلمة (سطحة، mobilisation…)",
  "how you want it written": "عايزها تتكتب إزاي",
  "Teach it": "علّمه",
  "Write the rule in the first box": "اكتب القاعدة في المربع الأول",
  "or save the first box as a writing rule — “always state VAT separately”": "أو احفظ المربع الأول كقاعدة كتابة — «اكتب ضريبة القيمة المضافة لوحدها دايمًا»",
  "Before it learns “": "قبل ما يتعلّم «",
  "Save it anyway": "احفظ برضه",
