  "Worth a second look": "محتاجة بصّة تانية",
  "keeps firing but never shows up in the answer": "بتشتغل كتير بس عمرها ما بتظهر في الرد",
  "never matched anything yet": "لسه ماطابقتش أي حاجة",
  "Only flagged, never removed on its own — it's your vocabulary, not ours.": "بننبّه بس، ومش بنمسح حاجة لوحدنا — دي كلماتك إنت، مش بتاعتنا.",
  "You keep using these — should it know them?": "بتستخدم الكلمات دي كتير — عايزه يتعلّمها؟",
  "Tap one to fill it in. Nothing is learned until you say so.": "دوس على واحدة عشان تتملا. مفيش حاجة هتتعلّم غير لما توافق.",
  "Nothing yet. The fastest way to start: when an answer uses the wrong word, tap “a word is wrong” under it.": "لسه مفيش حاجة. أسرع طريقة تبدأ: لما رد يستخدم كلمة غلط، دوس «فيه كلمة غلط» تحته.",
  "What it has learned from your corrections": "اللي اتعلّمه من تصحيحاتك",
  "Your examples were used on": "أمثلتك اتستخدمت في",
