  "recent answers and you still corrected": "رد قريب، ولسه بتصحّح",
  "% of them. They are not landing — the examples may be too varied, or the model too small for the task.": "% منهم. الأمثلة مش بتأثّر — يمكن متنوعة زيادة، أو النموذج أصغر من المهمة.",
