  "Instant, and with no model call — so it works with the radio off and costs no battery.": "فوري، ومن غير ما يشغّل النموذج — فبيشتغل والنت مقفول ومش بياكل بطارية.",
  "Nothing matches that yet.": "لسه مفيش حاجة مطابقة.",
  "Nothing yet. Use Instant, a photo or Travel and it lands here on its own —": "لسه مفيش حاجة. استخدم «فوري» أو صورة أو «السفر» وهيتحفظ هنا لوحده —",
  "you never have to save anything.": "ومش هتحتاج تحفظ أي حاجة خالص.",
