  "Every item carries the exact words it came from. If those words aren't in what you wrote, it never gets here — the app can miss something, but it cannot make one up.": "كل عنصر معاه الكلمات بالظبط اللي جه منها. لو الكلمات دي مش في اللي كتبته، عمره ما هيوصل هنا — التطبيق ممكن يفوّت حاجة، بس مش ممكن يألّف حاجة.",
