  "Checked": "آخر مراجعة",
  ". Entry rules change with no notice and the cost of being wrong is a denied boarding — confirm with the embassy or the official portal before you book.": ". قواعد الدخول ممكن تتغير من غير إنذار، والغلط ممكن يعني إنهم يمنعوك تركب الطيارة — اتأكد من السفارة أو البوابة الرسمية قبل ما تحجز.",
