  "all offline": "كلها من غير نت",
  "📶 Staying connected": "📶 خليك متصل",
  "Ask anything about being here": "اسأل أي حاجة عن وجودك هنا",
  "e.g. the taxi driver won't turn the meter on, what do I say? / is this price fair for a carpet? / can I drink the tap water?": "مثلًا: السواق مش عايز يشغّل العدّاد، أقول إيه؟ / السعر ده معقول لسجادة؟ / ينفع أشرب مية الحنفية؟",
  "It knows how things actually work here — fair prices, common overcharges, what's rude. It will tell you when something needs live data it can't have offline.": "عارف الدنيا ماشية إزاي هنا بجد — الأسعار المعقولة، والنصب المشهور في الأسعار، وإيه اللي يتعتبر قلة ذوق. وهيقولك لما حاجة تحتاج بيانات لحظية مش متاحة من غير نت.",
