  "Copied — show it to them": "اتنسخت — ورّيهالهم",
  "Tap to copy. These are written by hand, not generated — so an allergy or emergency phrase can never come out wrong.": "دوس عشان تنسخ. العبارات دي مكتوبة بإيد، مش متولّدة — فعبارة الحساسية أو الطوارئ مستحيل تطلع غلط.",
  "Pick a country above to download its pack.": "اختار دولة فوق عشان تنزّل باقتها.",
  "Anything to add? (optional)": "عايز تضيف حاجة؟ (اختياري)",
