  "Records replicate between your team's devices whenever any connection exists — site Wi-Fi, a company hub, or when someone drives back into coverage. The AI model never syncs; only small text records do, and they stay inside your company.": "السجلات بتتنسخ بين أجهزة فريقك أول ما يبقى فيه أي اتصال — Wi-Fi الموقع، أو جهاز الشركة الرئيسي، أو لما حد يرجع لمكان فيه تغطية. نموذج الذكاء الاصطناعي عمره ما بيتزامن؛ بس السجلات النصية الصغيرة، وبتفضل جوه شركتك.",
