  "Keeps your meaning and facts exactly — changes only how it reads. The writing sample is optional but makes the biggest difference.": "بيحافظ على معناك ومعلوماتك بالظبط — وبيغيّر بس طريقة الكلام. عيّنة الكتابة اختيارية بس بتفرق أكتر حاجة.",
