  "Paste stiff or AI-sounding text, add a sample of your own writing, and it comes back in your voice — same meaning, human rhythm.": "الصق نص ناشف أو شكله مكتوب بالذكاء الاصطناعي، وضيف عيّنة من كتابتك، وهيرجع بأسلوبك — نفس المعنى، بإيقاع بني آدم.",
  "Chat through Attune — it reads the whole conversation and sharpens every next prompt.": "اتكلم من خلال Attune — بيقرا المحادثة كلها وبيحسّن كل طلب بعدها.",
