  "Optimize my prompt": "حسّن طلبي",
  "The loop: type intent → get an optimized prompt → send it → bring the reply back → each next prompt is sharper. In the phone app, the share-sheet replaces copy-paste entirely.": "الدايرة: اكتب اللي عايزه ← خد طلب محسّن ← ابعته ← رجّع الرد ← كل طلب بعده بيبقى أدق. في تطبيق الموبايل، قايمة المشاركة بتغنيك عن النسخ واللصق خالص.",
