  "Your real names for your real things. Every document then uses them correctly — no invented equipment names, no wrong site spellings. Stays on your devices.": "أساميك الحقيقية لحاجاتك الحقيقية. كل المستندات بعدها هتستخدمها صح — من غير أسامي معدات متألّفة، ولا غلط في كتابة أسامي المواقع. بتفضل على أجهزتك.",
