  "Reporting rules": "قواعد التقارير",
  "e.g. every incident must state whether work was stopped; always record permit number": "مثلًا: كل حادثة لازم تقول الشغل وقف ولا لأ؛ وسجّل رقم التصريح دايمًا",
  "This is added to every field document — and it's also what your own adapter trains on, so the model learns your operation, not a generic one.": "ده بيتضاف لكل مستند ميداني — وهو كمان اللي المحوّل بتاعك بيتدرّب عليه، فالنموذج بيتعلّم شغلك إنت، مش شغل عام.",
