  "Keep everything on this phone and add the backup's chats, memory, reminders and cycle days. The Money ledger is only taken from the backup if this phone has none.": "خلّي كل اللي على الموبايل ده وضيف عليه محادثات النسخة وذاكرتها وتذكيراتها وأيام الدورة. دفتر الفلوس مش هيتاخد من النسخة غير لو الموبايل ده مفيهوش دفتر.",
