  "Work with another AI": "اشتغل مع ذكاء اصطناعي تاني",
  "Handles structure well; tags survive compression.": "بيتعامل مع البنية كويس؛ والوسوم بتفضل بعد الضغط.",
  "Name the outcome; it fills in the path.": "قول النتيجة اللي عايزها؛ وهو يكمّل الطريق.",
  "Huge window — compress for cost, not for fit.": "نافذة ضخمة — اضغط عشان توفّر، مش عشان يكفّي.",
  "Direct phrasing; ask for reasoning explicitly.": "كلام مباشر؛ واطلب التعليل صراحةً.",
  "Structured reasoning; keep numbered steps.": "تفكير منظّم؛ خلّي الخطوات المترقّمة.",
  "Strong multilingual — keep the source language.": "قوي في لغات كتير — خلّي لغة المصدر زي ما هي.",
  "Concise by nature; over-compressing loses nuance.": "مختصر بطبعه؛ والضغط الزيادة بيضيّع التفاصيل الدقيقة.",
  "Open weights; explicit instructions beat implied ones.": "أوزان مفتوحة؛ التعليمات الصريحة أحسن من الضمنية.",
  "Long documents are its strength; keep headings.": "المستندات الطويلة نقطة قوته؛ خلّي العناوين.",
  "Code context competes for the window — trim prose first.": "سياق الكود بيزاحم على النافذة — قصّ الكلام الأول.",
  "A search tool — keep the sources, cut the styling.": "أداة بحث — خلّي المصادر، وشيل التنسيق.",
  "On-device 1B": "على الجهاز 1B",
  "Tight. Cut everything that isn't the instruction.": "ضيقة. شيل أي حاجة مش تعليمات.",
  "On-device 3B": "على الجهاز 3B",
  "Room for a short history, not a long one.": "تساع سجل قصير، مش طويل.",
  "On-device 8B": "على الجهاز 8B",
  "Same window; better at using what's in it.": "نفس النافذة؛ بس أشطر في استخدام اللي فيها.",
  "Ed25519": "Ed25519",
  "Activated offline — it will bind to this device the next time there's a connection.": "اتفعّل من غير نت — هيتربط بالجهاز ده أول ما يبقى فيه نت.",
  "Couldn't reach activation — running on the key's signature for now.": "موصلناش لسيرفر التفعيل — شغال بتوقيع المفتاح دلوقتي.",
