  "35B of knowledge, 3B doing the work on each token — near-frontier answers at a speed a laptop can sustain. A mixture-of-experts model keeps every expert in memory even though few run per token, so this needs the RAM of a 35B and the compute of a 3B.": "معرفة نموذج 35B، و3B بس بتشتغل على كل رمز — إجابات قريبة من أقوى النماذج بسرعة اللابتوب يقدر يستحملها. نموذج «خليط الخبراء» بيشيل كل الخبراء في الذاكرة مع إن قليل منهم بيشتغل لكل رمز، عشان كده محتاج ذاكرة نموذج 35B وحوسبة نموذج 3B.",
