  "Can run {m}": "يقدر يشغّل {m}",
  "Detected about {n} GB of memory": "لقينا ذاكرة حوالي {n} جيجابايت",
  "Your phone reports {n} GB of memory": "موبايلك بيقول إن ذاكرته {n} جيجابايت",
  "Your computer reports {n} GB of memory": "الكمبيوتر بيقول إن ذاكرته {n} جيجابايت",
  "which leaves plenty of room for long conversations": "ودي مساحة كبيرة للمحادثات الطويلة",
  "which is comfortable for everyday use": "ودي مريحة للاستخدام اليومي",
  "which is enough, with shorter conversations": "ودي كفاية، بس المحادثات تبقى أقصر",
  ", ": "، ",
  "Documents, fleet records, copilot, every domain pack": "المستندات، سجلات الأسطول، المساعد، كل حزم المجالات",
  "Download it on Wi-Fi. After that it never uses your connection again.": "نزّله على Wi-Fi. بعد كده عمره ما هيستخدم النت بتاعك تاني.",
  "Small enough to download on mobile data if you need to.": "صغير كفاية تنزّله بباقة الموبايل لو احتجت.",
  "This is a large model for a phone. It will run, and it will slow down noticeably once the phone gets warm — keep answers short, or pick the smaller one.": "ده نموذج كبير على الموبايل. هيشتغل، بس هيبطّأ قوي لما الموبايل يسخن — خلّي الإجابات قصيرة، أو اختار الأصغر.",
  "Download {m} · {s} GB": "نزّل {m} · {s} جيجابايت",
  "Every tool, and all 31 country packs": "كل الأدوات، وكل حزم الدول الـ31",
  "Finds what you promised people, from your own words": "بيلاقي اللي وعدت بيه الناس، من كلامك إنت",
  "Fixed randomness, so a workflow gives identical output every time it runs.": "عشوائية ثابتة، فسير العمل يطلّع نفس النتيجة كل مرة.",
  "Free web search: DuckDuckGo, Bing and Mojeek at once, then the top pages are read in full, so answers come from real passages.": "بحث مجاني على النت: بيسأل DuckDuckGo وBing وMojeek مع بعض، وبعدين يقرا أهم الصفحات كاملة، فالإجابات تيجي من نصوص حقيقية.",
  "Free · no key": "مجاني · من غير مفتاح",
  "Install · {s}": "ثبّت · {s}",
  "Installing… {p}%": "بيثبّت… {p}%",
  "It remembers everything and can search it": "بيفتكر كل حاجة ويقدر يدوّر فيها",
  "Learns your vocabulary and writes the way you do": "بيتعلّم كلامك ويكتب بطريقتك",
  "Long answers": "إجابات طويلة",
  "No account, no sign-in, nothing uploaded": "من غير حساب، ولا تسجيل دخول، ومفيش حاجة بتترفع",
  "Not running": "مش شغال",
  "Running": "شغال",
  "Loading the model…": "بيحمّل النموذج…",
  "Nothing in the app can reach the internet — no web lookup, no maps, no downloads. The model and everything on the phone keep working.": "مفيش حاجة في التطبيق تقدر توصل للنت — لا بحث، ولا خرايط، ولا تنزيلات. النموذج وكل حاجة على الموبايل شغالين عادي.",
  "Offline lock": "قفل النت",
  "Same question, same answer": "نفس السؤال، نفس الإجابة",
  "The model reasons first on every question. Clearly better on hard problems, but on a phone the answer starts 30–90 s later. Off: tap “Think” on just the questions that need it.": "النموذج بيفكّر الأول في كل سؤال. أحسن بكتير في المسائل الصعبة، بس على الموبايل الإجابة بتبدأ بعد 30–90 ثانية. لو مقفول: دوس «فكّر» في الأسئلة اللي محتاجاه بس.",
  "The same model as below, given the memory to hold a whole book of context at once. On a 48 GB machine the spare RAM is better spent on context than on precision — you can hand it an entire contract or a year of notes and it keeps all of it in view.": "نفس النموذج اللي تحت، بذاكرة تشيل كتاب كامل من السياق مرة واحدة. على جهاز ذاكرته 48 جيجابايت، الذاكرة الزيادة أحسن تروح للسياق مش للدقة — تقدر تديله عقد كامل أو ملاحظات سنة كاملة ويفضل شايفها كلها.",
  "The whole assistant, on your device": "المساعد كله، على جهازك",
  "Works entirely offline. No account, ever.": "شغال من غير نت خالص. ومن غير حساب أبدًا.",
