  "Clock opened with the timer filled in — it starts there.": "الساعة اتفتحت والمؤقّت جاهز — بيبدأ من هناك.",
  "Calendar opened with the event filled in · {when} — tap Save there.": "التقويم اتفتح والموعد جاهز · {when} — دوس «حفظ» هناك.",
