  "Reminders & actions": "التذكيرات والإجراءات",
  "Just say it in Chat: “remind me tomorrow at 9 to call Ahmed”, “صحيني الساعة 6”, “ابعت لمحمود على الواتساب إني هتأخر”. You always confirm first.": "قولها في المحادثة: «فكّرني بكرة الساعة 9 أكلّم أحمد»، «صحّيني الساعة 6»، «ابعت لمحمود على الواتساب إني هتأخر». وإنت دايمًا بتأكّد الأول.",
  "Notifications are off for Attune — tap to allow them, or reminders can't appear.": "الإشعارات مقفولة لـ Attune — دوس عشان تسمح بيها، وإلا التذكيرات مش هتظهر.",
  "Reminders may come up to 10 minutes late. Tap to allow “Alarms & reminders” for Attune so they ring on the minute.": "التذكيرات ممكن تتأخر لحد 10 دقايق. دوس واسمح بـ«المنبّهات والتذكيرات» لـ Attune عشان ترن في معادها بالظبط.",
  "In the browser reminders are only listed — the Android app rings them.": "في المتصفح التذكيرات بتتعرض بس — الرنّ بيشتغل في تطبيق أندرويد.",
  "Add one": "ضيف تذكير",
