  "3-second gust from the crane's anemometer or a meter.": "هبّة 3 ثواني من مقياس الرياح في الونش أو جهاز قياس.",
  "Anything else under the tip": "أي حاجة تانية تحت راس البوم",
  "Best: from the manufacturer's outrigger calculator for this lift. Leave empty to estimate.": "الأحسن: من حاسبة الرجول بتاعة المصنّع للرفعة دي. سيبها فاضية للتقدير.",
