  "Code that is tested before you get it": "كود بيتجرّب قبل ما يوصلك",
  "Failed": "فشل",
  "Fix it automatically": "صلّحه لوحده",
  "From chat": "من المحادثة",
  "Hide preview": "اخفي المعاينة",
  "JavaScript": "JavaScript",
  "Make this program work correctly.": "خلّي البرنامج ده يشتغل صح.",
  "Making the change…": "بيعدّل…",
  "New": "جديد",
  "Not passing yet": "لسه مانجحش",
  "Passed its {n} tests": "نجح في {n} اختبارات",
  "Preview": "معاينة",
  "Programs tested on your phone": "برامج بتتجرّب على موبايلك",
  "Python": "Python",
