  "The model writes the program and its tests, the phone runs them, and any error goes straight back to the model to fix — until the tests pass. Offline, in a locked sandbox.": "النموذج بيكتب البرنامج واختباراته، والموبايل بيشغّلهم، وأي غلطة بترجع على طول للنموذج يصلّحها — لحد ما الاختبارات تنجح. من غير نت، في صندوق مقفول.",
