  "Only the first parts of this long document were summarised.": "اتلخّصت الأجزاء الأولى بس من المستند الطويل ده.",
  "Open a PDF, Word file, book or web page. Read it here and chat with it — every answer shows the page it came from. Everything stays on your phone.": "افتح PDF أو وورد أو كتاب أو صفحة ويب. اقراه هنا واتكلم معاه — كل إجابة بتوريك الصفحة اللي جت منها. وكل حاجة بتفضل على موبايلك.",
  "Open a file": "افتح ملف",
