  "Page {n}": "صفحة {n}",
  "Pick a PDF, Word, PowerPoint, e-book, web page or text file.": "اختار PDF أو وورد أو باوربوينت أو كتاب إلكتروني أو صفحة ويب أو ملف نصي.",
  "Pick the file again to continue — files are not copied into the app.": "اختار الملف تاني عشان تكمّل — الملفات مابتتنسخش جوه التطبيق.",
  "Read pages": "الصفحات اللي اتقرت",
  "Reading and searching work now. To chat with the file, install a model in Engine.": "القراية والبحث شغالين دلوقتي. عشان تتكلم مع الملف، ثبّت نموذج من «المحرك».",
