  "The AI is reading scanned page {n}…": "الذكاء الاصطناعي بيقرا الصفحة المتصوّرة {n}…",
  "There is no readable text in this file.": "مفيش نص يتقري في الملف ده.",
  "This answer could not be tied to a page — check the pages listed below before relying on it.": "ماقدرناش نربط الإجابة دي بصفحة — راجع الصفحات اللي تحت قبل ما تعتمد عليها.",
  "Writing the answer…": "بيكتب الإجابة…",
