  "Checklist: what every answer must satisfy (one per line, optional)": "قايمة مراجعة: اللي لازم كل إجابة تحققه (بند في كل سطر، اختياري)",
  "Facts the AI should know (prices, rules, terms — optional)": "معلومات لازم الذكاء الاصطناعي يعرفها (أسعار، قواعد، شروط — اختياري)",
  "Separate topics with an empty line. Only the paragraphs that fit the question are used, so this can be long.": "افصل بين المواضيع بسطر فاضي. بنستخدم بس الفقرات اللي تناسب السؤال، فممكن يكون طويل.",
  "Facts": "المعلومات",
  "It also runs this small program on your phone (offline, in a locked box — no internet, no files, no access to the app)": "وكمان بيشغّل البرنامج الصغير ده على موبايلك (من غير نت، في صندوق مقفول — لا نت، ولا ملفات، ولا وصول للتطبيق)",
  "Edit or improve my CV": "عدّل أو حسّن الـ CV بتاعي",
  "Say what to add or change («add my job at Dar Al Fouad Hospital as a nurse, 2019–2022», «change my phone to …»), or leave it empty and just make it more professional. You see the result before it is kept.": "اكتب عايز تضيف أو تغيّر إيه («ضيف شغلي في مستشفى دار الفؤاد ممرضة، 2019–2022»، «غيّر رقمي لـ …»)، أو سيبه فاضي عشان تبقى أكتر احترافية بس. هتشوف النتيجة قبل ما تتحفظ.",
  "What should be added or changed? (optional)": "عايز تضيف أو تغيّر إيه؟ (اختياري)",
