  "Create": "اعمل",
  "Current photo quality in 4 steps: people, places, products and text in pictures. Also edits a photo you give it (“make it night”, “remove the car”).": "صور بجودة حديثة في 4 خطوات: ناس وأماكن ومنتجات وكلام جوه الصورة. وكمان بيعدّل صورة تديهاله («خلّيها بالليل»، «شيل العربية»).",
  "Describe the picture, in Arabic or English — e.g. “a felucca on the Nile at sunset”": "وصّف الصورة بالعربي أو الإنجليزي — مثلًا «فلوكة في النيل وقت الغروب»",
  "Developing the picture…": "بيطلّع الصورة…",
