  "Each picture is made by a separate engine process: when it finishes, all its memory goes back to the phone. Nothing is uploaded.": "كل صورة بتتعمل في عملية لوحدها: ولما تخلص كل ذاكرتها بترجع للموبايل. ومفيش حاجة بتترفع.",
