  "Studio draws pictures with the phone's own chip — it works in the Android app.": "«الاستوديو» بيرسم الصور بشريحة الموبايل نفسه — وبيشتغل في تطبيق أندرويد.",
  "Studio works in the Android app.": "«الاستوديو» بيشتغل في تطبيق أندرويد.",
  "The chat model was paused to make room, and is loading again.": "نموذج المحادثة وقف شوية عشان نوفّر مساحة، وبيتحمّل تاني دلوقتي.",
  "This APK has no picture engine yet — it comes with the next APK built on GitHub.": "الـ APK ده لسه مفيهوش محرك صور — هييجي مع الـ APK الجاي اللي بيتبني على GitHub.",
  "This build draws on the CPU.": "النسخة دي بترسم على المعالج.",
  "This build of the app has no picture engine yet.": "النسخة دي من التطبيق لسه مفيهاش محرك صور.",
  "This phone has {n} GB — it may be too little for pictures.": "الموبايل ده ذاكرته {n} جيجابايت — ممكن تبقى قليلة على الصور.",
  "This version of Attune has no graphics-chip picture engine, so pictures are drawn on the CPU (slower). An update adds it.": "النسخة دي من Attune مفيهاش محرك صور على شريحة الرسوميات، فالصور بتترسم على المعالج (أبطأ). تحديث جاي هيضيفه.",
  "The picture engine stopped responding while loading the model, so it was stopped. Engine → Engine log shows its last lines — send them to support.": "محرك الصور بطّل يرد وهو بيحمّل النموذج، فاتقفل. آخر سطوره في «المحرك» ← «سجل المحرك» — ابعتها للدعم.",
  "This phone's GPU driver did not answer, so pictures are drawn on the CPU (slower).": "تعريف GPU في الموبايل ده ماردّش، فالصور بتترسم على المعالج (أبطأ).",
  "What should change? e.g. “make it night, with the street lights on”": "إيه اللي يتغيّر؟ مثلًا «خلّيها بالليل وأنوار الشارع منوّرة»",
  "Write a fuller description first (better pictures; uses the chat model)": "اكتب وصف أكمل الأول (صور أحسن؛ بيستخدم نموذج المحادثة)",
  "Writing a fuller description…": "بيكتب وصف أكمل…",
