  "I couldn't make every test pass yet — here is the closest version; tap “Test & fix in Code” to keep going.": "لسه ماقدرتش أنجّح كل الاختبارات — دي أقرب نسخة؛ دوس «جرّب وصلّح في الكود» عشان تكمّل.",
  "Working it out as a program…": "بيحلّها كبرنامج…",
