  "FLUX.2 klein 4B · high quality": "FLUX.2 klein 4B · جودة عالية",
  "The best pictures this phone can make: the 8-bit build of FLUX.2 klein — finer detail, cleaner faces, hands and text. Also edits your photos by instruction.": "أحسن صور الموبايل ده يقدر يعملها: نسخة 8-بت من FLUX.2 klein — تفاصيل أدق، ووشوش وإيدين وكلام أوضح. وكمان بيعدّل صورك بالتعليمات.",
  "Spreadsheet or document": "شيت أو مستند",
  "That file is too large (15 MB at most)": "الملف كبير قوي (15 ميجابايت بالكتير)",
  "What's in this file? Summarise what matters.": "إيه اللي في الملف ده؟ لخّص المهم.",
  "Checked — the reviewer fixed a mistake": "اتراجع — المراجِع صلّح غلطة",
