  "{v} of {n} tries agreed · checked": "{v} من {n} محاولات اتفقوا · اتراجع",
  "Computed from {f} on this phone": "اتحسب من {f} على الموبايل ده",
  "Used {n} of your corrections": "استخدم {n} من تصحيحاتك",
  "Wrong? Teach the right answer": "غلط؟ علّمه الإجابة الصح",
  "What should it have said? Chat will answer this way next time you ask something like it.": "كان المفروض يقول إيه؟ «الشات» هيرد كده المرة الجاية لما تسأل حاجة شبهه.",
  "The right answer": "الإجابة الصح",
  "Why (optional) — e.g. “the marble falls out when the glass is turned over”": "السبب (اختياري) — مثلًا «البلية بتقع لما الكوباية تتقلب»",
  "Learned — Chat will use this on similar questions": "اتعلّم — «الشات» هيستخدم ده في الأسئلة اللي شبهه",
  "That is the same as the answer — nothing to learn": "دي نفس الإجابة — مفيش حاجة يتعلّمها",
  "Thinking it through…": "بيفكّر فيها…",
