  "Could not check it: {e}": "ماقدرناش نراجع: {e}",
  "Could not check it (no answer from the model).": "ماقدرناش نراجع (النموذج ماردّش).",
  "The phone's storage for Business is full — export a table to CSV and delete old records.": "مساحة «الأعمال» على الموبايل اتملت — صدّر جدول CSV وامسح السجلات القديمة.",
  "Created — {n} tables": "اتعمل — {n} جداول",
  "Deleted": "اتمسح",
