  "A project keeps related chats together with shared instructions and your own files — like a folder the assistant has read.": "المشروع بيجمع المحادثات اللي ليها علاقة ببعض مع تعليمات مشتركة وملفاتك — زي فولدر المساعد قراه.",
  "New project": "مشروع جديد",
  "No projects yet.": "لسه مفيش مشاريع.",
