  "File": "ملف",
  "Web pages, documents and programs from your chats. Open one to preview it full screen, change it by asking, or save it as a file.": "صفحات ويب ومستندات وبرامج من محادثاتك. افتح أي واحد تشوفه بملء الشاشة، أو عدّله بطلب، أو احفظه كملف.",
  "No artifacts yet.": "لسه مفيش شغل محفوظ.",
  "Ask Chat for a website, a report or a program, then tap its card and Save.": "اطلب من «المحادثة» موقع أو تقرير أو برنامج، وبعدين دوس على الكارت واختار «احفظ».",
