  "Forget": "انسى",
  "Delete this action?": "تمسح الإجراء ده؟",
  "RAM: needs {n} GB · smooth from {s} GB": "الرامات: محتاج {n} جيجابايت · بيشتغل بسلاسة من {s} جيجابايت",
  "runs smoothly on this device ({n} GB)": "بيشتغل بسلاسة على الجهاز ده ({n} جيجابايت)",
  "runs on this device ({n} GB), slower": "بيشتغل على الجهاز ده ({n} جيجابايت)، بس أبطأ",
  "this device has {n} GB — too little": "الجهاز ده فيه {n} جيجابايت — قليل",
  "Spark (helper)": "Spark (مساعد)",
  "Only works with Spark, Glow, Core and Zenith — not with the model in use.": "بيشتغل مع Spark وGlow وCore وZenith بس — مش مع الموديل الحالي.",
  "Download Spark as a helper (about 0.5 GB, once). Works with Glow, Core and Zenith.": "نزّل Spark كمساعد (حوالي 0.5 جيجابايت، مرة واحدة). بيشتغل مع Glow وCore وZenith.",
  "This is a big model for a phone — Core is about 2–3× faster.": "ده موديل كبير على الموبايل — Core أسرع حوالي 2–3 مرات.",
  "Everest with a huge memory: it holds a whole book, contract or a year of notes at once. The best for very long documents. Computer-class.": "Everest بذاكرة ضخمة: بيشيل كتاب كامل أو عقد أو ملاحظات سنة كاملة مرة واحدة. الأحسن للمستندات الطويلة أوي. للكمبيوتر.",
  "The most knowledgeable: a very large model that answers at the speed of a small one (mixture of experts). Near top-tier answers. Computer-class.": "الأوسع معرفة: موديل ضخم بيرد بسرعة موديل صغير (خليط الخبراء). إجابات قريبة من أعلى مستوى. للكمبيوتر.",
  "The strongest single model here: deep reasoning, expert writing, reads photos. Computer-class.": "أقوى موديل لوحده هنا: تفكير عميق، وكتابة بمستوى خبير، وبيقرا الصور. للكمبيوتر.",
  "Close to Apex+ quality at a much higher speed. Reads photos. For strong laptops.": "جودة قريبة من Apex+ وبسرعة أعلى بكتير. بيقرا الصور. للابتوبات القوية.",
  "Expert level, and reads text, photos and audio. Comfortable on a laptop or a 16 GB phone.": "مستوى خبير، وبيقرا الكلام والصور والصوت. مريح على لابتوب أو موبايل 16 جيجابايت.",
  "The strongest model a 12 GB phone can run: expert answers, and the best at reading documents and photos.": "أقوى موديل يشتغل على موبايل 12 جيجابايت: إجابات بمستوى خبير، والأحسن في قراية المستندات والصور.",
  "The fast one: runs on the phone's graphics chip — the first words appear in under a second. Reads photos, English and Arabic. For harder questions, Blaze+ is stronger.": "السريع: بيشتغل على شريحة الرسوميات في الموبايل — أول كلام بيظهر في أقل من ثانية. بيقرا الصور والإنجليزي والعربي. وللأسئلة الأصعب، Blaze+ أقوى.",
  "The stronger fast one: noticeably better answers than Blaze, still on the graphics chip — first words in about a second.": "السريع الأقوى: إجابات أحسن بوضوح من Blaze، وبرضه على شريحة الرسوميات — أول كلام في حوالي ثانية.",
  "The best everyday choice if your phone can hold it: reads photos of documents and receipts, Arabic and English, with extra precision for long answers.": "أحسن اختيار يومي لو موبايلك يشيله: بيقرا صور المستندات والإيصالات، عربي وإنجليزي، بدقة أعلى للإجابات الطويلة.",
  "Text, photos and audio on a flagship phone — pick it if you want voice notes understood.": "كلام وصور وصوت على موبايل فلاجشيب — اختاره لو عايزه يفهم الفويسات.",
  "The sweet spot on an ordinary modern phone: everything the app does, in under 3 GB.": "الاختيار المظبوط لموبايل حديث عادي: كل اللي التطبيق بيعمله، في أقل من 3 جيجابايت.",
  "Core made 10% smaller for a 4 GB phone — worth it over Glow.": "Core أصغر 10% لموبايل 4 جيجابايت — أحسن من Glow.",
  "Runs on a budget phone and still reads photos. Good short answers; long reasoning shows its size.": "بيشتغل على موبايل رخيص وبرضه بيقرا الصور. إجابات قصيرة كويسة؛ وفي التفكير الطويل حجمه بيبان.",
  "For a phone that can't hold anything else: tidying and shortening text. Not for reasoning.": "لموبايل مش شايل غيره: ترتيب الكلام واختصاره. مش للتفكير.",
  "Blaze on the graphics chip: first words in about a second, many times faster than this engine. {s} GB, once.": "Blaze على شريحة الرسوميات: أول كلام في حوالي ثانية، وأسرع من المحرك ده بكتير. {s} جيجابايت، مرة واحدة.",
  "The biggest speed-up on this phone is the fast engine: Blaze on the graphics chip — first words in about a second. Tap “Switch to the fast engine” above.": "أكبر تسريع على الموبايل ده هو المحرك السريع: Blaze على شريحة الرسوميات — أول كلام في حوالي ثانية. دوس «حوّل للمحرك السريع» فوق.",
