  "Explicit action verbs beat vague asks (Anthropic 2026)": "الأفعال الواضحة أحسن من الطلبات المبهمة (Anthropic 2026)",
  "State the desired outcome, not steps (OpenAI 2026)": "قول النتيجة اللي عايزها، مش الخطوات (OpenAI 2026)",
  "Concise prompts cut cost ~76% and lift quality": "الطلبات المختصرة بتوفّر حوالي 76% من التكلفة وبتحسّن الجودة",
  "Style examples outperform adjectives like 'professional'": "أمثلة الأسلوب أحسن من صفات زي «احترافي»",
  "Scoping the edit prevents unwanted rewrites": "تحديد حدود التعديل بيمنع إعادة كتابة مش عايزها",
  "Naming the goal and constraint shapes register": "ذكر الهدف والقيود بيظبط نبرة الكلام",
  "Put the ask after the data (Gemini/GPT guidance)": "حط الطلب بعد البيانات (إرشادات Gemini/GPT)",
  "Define the output shape explicitly": "حدّد شكل النتيجة بوضوح",
  "Name the goal so the model reasons toward it": "سمّي الهدف عشان تفكير الموديل يروح ناحيته",
  "Specificity → fewer misinterpretations": "التحديد ← سوء فهم أقل",
  "Goal-framing beats tone adjectives alone": "تحديد الهدف أحسن من صفات النبرة لوحدها",
  "Data first, question last improves grounding": "البيانات الأول والسؤال في الآخر بيحسّن الاعتماد على المصدر",
  "Role-free outcome framing (2026 guidance)": "وصف النتيجة من غير أدوار (إرشادات 2026)",
  "Explicit output shape reduces rework": "الشكل الواضح للنتيجة بيقلّل إعادة الشغل",
  "Goal + constraint framing produces usable scripts": "الهدف مع القيود بيطلّع نصوص تتستخدم على طول",
  "Stated criteria prevent generic pro/con lists": "المعايير الواضحة بتمنع قوايم المزايا والعيوب العامة",
  "Concrete constraints beat generic advice": "القيود المحددة أحسن من النصايح العامة",
  "Time constraints force actionable plans": "قيود الوقت بتطلّع خطط تتنفّذ",
  "Matching to the posting outperforms templates": "المطابقة مع إعلان الوظيفة أحسن من القوالب",
  "Role-specific prompting beats generic question lists": "الطلب الخاص بالوظيفة أحسن من قوايم الأسئلة العامة",
  "Source-anchored prompts reduce invented detail": "ربط الطلب بمصدر بيقلّل التفاصيل المتألفة",
  "Constraints up front prevent generic travel advice": "ذكر القيود من الأول بيمنع نصايح السفر العامة",
  "Explaining the 'why' improves targeting (Anthropic)": "شرح «ليه» بيحسّن الدقة (Anthropic)",
  "Search tools need source + recency constraints": "أدوات البحث محتاجة تحديد المصادر وقد إيه المعلومة جديدة",
  "Constraints up front prevent generic answers": "ذكر القيود من الأول بيمنع الإجابات العامة",
  "Active recall outperforms re-reading": "إنك تفتكر بنفسك أحسن من إعادة القراية",
  "Sectioned output aids comprehension": "تقسيم النتيجة لأجزاء بيسهّل الفهم",
  "Explicit critique requests beat 'what do you think'": "طلب النقد الصريح أحسن من «إيه رأيك؟»",
  "Naming review axes prevents shallow feedback": "تحديد محاور المراجعة بيمنع الملاحظات السطحية",
  "Include context + attempted fixes for accuracy": "اذكر السياق واللي جرّبته عشان دقة أكبر",
  "Section-by-section output beats 'write a page'": "الكتابة جزء جزء أحسن من «اكتب صفحة»",
  "Persona-specific prompts improve targeting": "الطلب الموجّه لجمهور محدد بيحسّن الدقة",
  "Stating criteria prevents generic pro/con lists": "ذكر المعايير بيمنع قوايم المزايا والعيوب العامة",
  "Level-setting improves explanation fit": "تحديد المستوى بيخلّي الشرح مناسب",
  "Specifying length prevents rambling summaries": "تحديد الطول بيمنع الملخصات الطويلة",
  "Ask to implement, not 'suggest changes' (Anthropic)": "اطلب التنفيذ، مش «اقترح تعديلات» (Anthropic)",
  "Reasoning models excel with clear scope, no examples": "موديلات التفكير بتبقى أحسن مع حدود واضحة ومن غير أمثلة",
  "Name every state so nothing is left ambiguous": "سمّي كل حالة عشان مفيش حاجة تفضل مبهمة",
  "Natural language + explicit variety works on GPT": "الكلام الطبيعي مع طلب التنوع بوضوح بينفع مع GPT",
  "Outcome framing beats feature lists": "وصف النتيجة أحسن من قوايم المزايا",
  "Gemini prefers direct, constrained prompts": "Gemini بيحب الطلبات المباشرة المحددة",
  "Short + specific tone yields natural output": "النبرة القصيرة المحددة بتطلّع كلام طبيعي",
  "Chain-of-thought: +~40% avg on hard reasoning (Wei et al.); MultiArith 18%→79%. Skip on reasoning models — minimal gain, more latency.": "التفكير خطوة بخطوة: حوالي +40% في المسائل الصعبة (Wei وآخرين)؛ MultiArith من 18% لـ 79%. متستخدموش مع موديلات التفكير — فايدة قليلة وبطء أكتر.",
  "1–5 examples (few-shot) raise pattern-task accuracy up to +43%; best on non-reasoning models like Gemini. Don't add examples for pure reasoning tasks — can hurt.": "من 1 لـ 5 أمثلة بترفع دقة المهام المتكررة لحد +43%؛ وأحسن مع الموديلات اللي مش متخصصة في التفكير زي Gemini. متضيفش أمثلة لمهام التفكير البحت — ممكن تضر.",
  "OpenAI/Anthropic 2026: describe what a good result looks like; over-instructing adds noise on modern models.": "OpenAI/Anthropic 2026: اوصف شكل النتيجة الكويسة؛ كتر التعليمات بيشوّش الموديلات الحديثة.",
  "2026 practice: set how hard to think (thinking/effort control) and spend words on the outcome, not on 'think step by step'.": "أسلوب 2026: حدّد قد إيه يفكّر (التحكم في المجهود) وركّز كلامك على النتيجة، مش على «فكّر خطوة بخطوة».",
  "Clarification-first reduces wasted turns — the model gathers missing context instead of guessing.": "إنك تبدأ بالاستفسار بيوفّر جولات ضايعة — الموديل بيجمع السياق الناقص بدل ما يخمّن.",
  "Outcome criteria (what 'good' means) outperform process instructions on 2026 models.": "معايير النتيجة (يعني إيه «كويس») أحسن من تعليمات الطريقة في موديلات 2026.",
  "Verification steps reduce errors on factual/analytical tasks.": "خطوات التأكد بتقلّل الغلط في المهام الواقعية والتحليلية.",
  "Specific details produce specific writing": "التفاصيل المحددة بتطلّع كتابة محددة",
  "Structure-to-prose is a well-suited LLM task": "تحويل النقط لكلام متصل مهمة مناسبة للموديلات اللغوية",
  "Explicit sections prevent rambling updates": "الأقسام الواضحة بتمنع التحديثات الطويلة",
  "Asking for risks surfaces what you forgot": "السؤال عن المخاطر بيكشف اللي نسيته",
