  "The GPU driver stalled twice while loading the picture model, so Attune switched Studio to the CPU (you can try the GPU again below).": "تعريف شريحة الرسوميات وقف مرتين وهو بيحمّل موديل الصور، فـ Attune نقل «الاستوديو» للمعالج (تقدر تجرّب شريحة الرسوميات تاني تحت).",
