  "Nothing found for that — try the area's name too (e.g. “… New Cairo”), or move the map there and search again.": "ملقيناش حاجة — جرّب تضيف اسم المنطقة (مثلًا «… التجمع الخامس»)، أو حرّك الخريطة هناك ودوّر تاني.",
