  "This phone can't share its location with the app.": "الموبايل ده مش بيقدر يدي موقعه للتطبيق.",
  "Location is off for Attune — allow it in the phone's settings to see where you are.": "الموقع مقفول لـ Attune — اسمح بيه من إعدادات الموبايل عشان تشوف إنت فين.",
  "Couldn't get your location — check that location is on.": "معرفتش أحدد مكانك — اتأكد إن الموقع شغال.",
  "“{n}” isn't kept on this phone any more — pick the file again.": "«{n}» مبقاش محفوظ على الموبايل ده — اختار الملف تاني.",
  "tap to continue": "دوس عشان تكمّل",
  "The text and your questions are kept on this phone only. Forget removes them.": "النص وأسئلتك محفوظين على الموبايل ده بس. «انسى» بيمسحهم.",
  "Web · Auto": "النت · أوتوماتيك",
  "Web: Auto — it searches only when a question needs fresh facts": "النت: أوتوماتيك — بيدوّر بس لما السؤال يحتاج معلومات جديدة",
  "Pick the best model for each question": "اختار أحسن موديل لكل سؤال",
  "Reading your {f} conversation…": "بقرا محادثتك مع {f}…",
  "Reading the conversation…": "بقرا المحادثة…",
  "Shared links are opened in the Android app — or paste the conversation's text here.": "اللينكات المشتركة بتتفتح في تطبيق أندرويد — أو الصق كلام المحادثة هنا.",
  "I read your conversation with {f}{t} (about {n} words). Ask me anything about it — check it, summarise it, or carry on from where it stopped.": "قريت محادثتك مع {f}{t} (حوالي {n} كلمة). اسألني أي حاجة عنها — أراجعها، أو ألخصها، أو أكمّل من مكان ما وقفت.",
  "Attune · the AI runs on your device · no account, no sign-in · web lookup only when a question needs it (Auto) — switch it off with the Web button": "Attune · الذكاء الاصطناعي شغال على جهازك · من غير حساب ولا تسجيل دخول · البحث على النت بس لما السؤال يحتاجه (أوتوماتيك) — اقفله من زرار النت",
  "Web: Off — nothing is looked up": "النت: مقفول — مفيش أي بحث",
  "Search the web by itself when a question needs it": "دوّر على النت لوحدك لما السؤال يحتاج",
  "While Web is off in Chat, questions about prices, specs, news, scores or this year are still looked up (only the search words leave the phone). Off: nothing is looked up unless you turn Web on.": "حتى لو زرار النت مقفول في «المحادثة»، الأسئلة عن الأسعار والمواصفات والأخبار والنتايج وأحداث السنة دي بيتدوّر عليها (ومفيش حاجة بتطلع من الموبايل غير كلمات البحث). لو اتقفل: مفيش أي بحث إلا لو شغّلت زرار النت.",
  "Attune · the AI runs on your device · no account, no sign-in · web lookup only when a question needs it (Auto) — switch Auto off in Engine": "Attune · الذكاء الاصطناعي شغال على جهازك · من غير حساب ولا تسجيل دخول · البحث على النت بس لما السؤال يحتاجه (أوتوماتيك) — اقفل الأوتوماتيك من «المحرك»",
  "The model wrote nonsense — restarting it in safe mode and asking again…": "الموديل كتب كلام ملوش معنى — بشغّله تاني في الوضع الآمن وبسأل تاني…",
  "This model writes nonsense on this phone, even in safe mode. Pick another model in Engine (Core works well) and tell us which one failed.": "الموديل ده بيكتب كلام ملوش معنى على الموبايل ده حتى في الوضع الآمن. اختار موديل تاني من «المحرك» (Core شغال كويس) وقولنا أنهي واحد فشل.",
  "Safe mode is on for this model: it once wrote nonsense on this phone, so it runs without speed tricks and with full-precision memory (a little slower, same answers).": "الوضع الآمن شغال للموديل ده: كتب مرة كلام ملوش معنى على الموبايل ده، فبيشتغل دلوقتي من غير حيل التسريع وبذاكرة كاملة الدقة (أبطأ شوية، ونفس الإجابات).",
  "Turn safe mode off": "اقفل الوضع الآمن",
  "Ready courses": "كورسات جاهزة",
  "Or any topic you like": "أو أي موضوع إنت عايزه",
