  "Download a whole country once: every road, building, place and shop, and search — all with no signal. A new version is built every week from OpenStreetMap; the app tells you when one is ready.": "نزّل خريطة دولة كاملة مرة واحدة: كل شارع ومبنى ومكان ومحل، والبحث كمان — كله من غير نت. فيه نسخة جديدة بتتعمل كل أسبوع من OpenStreetMap، والتطبيق بيقولك لما تجهز.",
