  "With signal, every country here shows online without downloading — every street, compound and place. Download only to use it with no signal.": "لو فيه نت، كل دولة هنا بتظهر أونلاين من غير تنزيل — كل شارع وكمبوند ومكان. نزّلها بس لو هتستخدمها من غير نت.",
  "This map is not published yet": "الخريطة دي لسه منزلتش",
  "Download the world map to see every country, or your country's map for streets, places and offline search.": "نزّل خريطة العالم عشان تشوف كل الدول، أو خريطة بلدك للشوارع والأماكن والبحث من غير نت.",
