  "Download the whole map of {c}? {s} — on Wi-Fi is best. Every road, building, place and shop, and offline search.": "تنزّل خريطة {c} كلها؟ {s} — الأحسن على الواي فاي. كل شارع ومبنى ومكان ومحل، والبحث من غير نت.",
