  "Ask the airline for the reason: weather or an air-traffic strike would cancel it; a technical fault or crew shortage would not.": "اسأل شركة الطيران عن السبب: الجو الوحش أو إضراب المراقبة الجوية بيلغي حقك؛ إنما العطل الفني أو نقص الطاقم لأ.",
