  "No compensation": "مفيش تعويض",
  "Worked out from the published rules (EU 261, UK 261, Canada's APPR). Airlines sometimes refuse at first — a polite second letter or the national enforcement body usually settles it.": "محسوب من القواعد المنشورة (أوروبا 261، بريطانيا 261، لوايح كندا APPR). شركات الطيران ساعات بترفض في الأول — وغالبًا رسالة تانية بأدب أو الجهة الرقابية في البلد بتحل الموضوع.",
  "What you're owed": "ليك إيه",
  "Flight delayed or cancelled?": "رحلتك اتأخرت أو اتلغت؟",
  "See what the airline owes you — up to €600 — and get the letter": "اعرف شركة الطيران مديونالك بكام — لحد 600 يورو — وخد الرسالة",
  "Write the request": "اكتب الطلب",
  "Ask for it back": "اطلب ترجعه",
  "See what I'm owed": "ليا إيه؟",
  "A technical problem with the plane": "عطل فني في الطيارة",
  "Crew shortage or the airline's own staff strike": "نقص طاقم أو إضراب موظفين شركة الطيران",
  "Overbooking / operational reasons": "أوفر بوكينج / أسباب تشغيلية",
  "Bad weather": "الجو وحش",
  "Air-traffic control or airport strike": "المراقبة الجوية أو إضراب في المطار",
  "Security, political unrest, a bird strike, medical emergency": "أمن، اضطرابات سياسية، طير خبط في الطيارة، حالة طبية طارئة",
  "I don't know / they didn't say": "معرفش / مقالوش",
  "Which airport did you fly from?": "سافرت من أنهي مطار؟",
  "Which airport were you flying to?": "كنت رايح على أنهي مطار؟",
  "What happened — a delay, a cancellation, or you were refused boarding?": "حصل إيه — تأخير، ولا إلغاء، ولا رفضوا تطلع الطيارة؟",
  "How late did you ARRIVE (hours)?": "وصلت متأخر كام ساعة؟",
  "How many days before the flight were you told?": "قالولك قبل الرحلة بكام يوم؟",
  "Was the airline a European one? (EU rules cover flights INTO Europe only on European airlines)": "شركة الطيران أوروبية؟ (القواعد الأوروبية بتغطي الرحلات الجاية لأوروبا على الشركات الأوروبية بس)",
  "Was the airline a UK one? (UK rules cover flights INTO the UK only on UK airlines)": "شركة الطيران بريطانية؟ (القواعد البريطانية بتغطي الرحلات الجاية لبريطانيا على الشركات البريطانية بس)",
  "Which airline was it? (Canada's amounts depend on its size)": "أنهي شركة طيران؟ (مبالغ كندا بتفرق حسب حجم الشركة)",
  "How late did you arrive at your destination (hours)?": "وصلت وجهتك متأخر كام ساعة؟",
  "Over 3,500 km with a 3–4 hour delay: the airline may halve it.": "أكتر من 3,500 كم وتأخير 3–4 ساعات: شركة الطيران ممكن تنزله للنص.",
  "Told 7–13 days ahead: not owed if they offered a flight leaving at most 2 h earlier and arriving at most 4 h later than yours.": "قالولك قبلها بـ 7–13 يوم: مالكش حق لو عرضوا رحلة بتقوم قبل رحلتك بساعتين بالكتير وبتوصل بعدها بـ 4 ساعات بالكتير.",
  "Told under 7 days ahead: not owed only if they offered a flight leaving at most 1 h earlier and arriving at most 2 h later than yours.": "قالولك قبلها بأقل من 7 أيام: حقك مش بيضيع غير لو عرضوا رحلة بتقوم قبل رحلتك بساعة بالكتير وبتوصل بعدها بساعتين بالكتير.",
  "Owed when the delay was within the airline's control and not for safety. Claim within 1 year.": "ليك حق لو التأخير بسبب شركة الطيران ومش لأسباب سلامة. قدّم المطالبة خلال سنة.",
  "A delayed or cancelled flight — the airline may owe you money": "رحلة متأخرة أو ملغية — ممكن شركة الطيران تكون مديونالك بفلوس",
