  "What should Scout look for?": "الكشّاف يدوّر على إيه؟",
  "e.g. a 3-bedroom flat for rent in Maadi under 15,000, not ground floor": "زي: شقة ٣ أوض للإيجار في المعادي أقل من ١٥ ألف، مش دور أرضي",
