  "Scout checks each goal when you open Attune (at most twice a day), once at night on the phone, and whenever you tap Check now, and tells you only about strong new finds or price drops. It reads public ads only and never contacts anyone or pays for you.": "الكشّاف بيفحص كل هدف لما تفتح Attune (مرتين في اليوم بالكتير)، ومرة بالليل على الموبايل، وكل ما تدوس «افحص دلوقتي»، وبيقولك بس على اللقطات الجديدة القوية أو لما الأسعار تنزل. بيقرا الإعلانات العامة بس، ومش بيكلم حد ولا بيدفع عنك.",
  "Nothing that matches yet. Scout keeps looking — you'll be told when something good appears.": "مفيش حاجة مطابقة لسه. الكشّاف لسه بيدوّر — وهيقولك لما تظهر حاجة كويسة.",
