  "Runs the model on the Snapdragon NPU (Hexagon): much cooler, often faster at reading. Works best with Core Max (8-bit). Switches itself back to the CPU if anything goes wrong.": "بيشغّل النموذج على الـ NPU في سناب دراجون (Hexagon): أبرد بكتير وغالبًا أسرع في القراية. بيشتغل أحسن مع Core Max (8 بت). بيرجع للمعالج لوحده لو حصلت أي مشكلة.",
  "This phone's NPU could not be used by the engine — Attune stays on the CPU.": "المحرك معرفش يستخدم الـ NPU في الموبايل ده — Attune هيفضل على المعالج.",
  "Last time, starting on the NPU closed the app. Attune is back on the CPU; you can try it again in Engine → Speed.": "المرة اللي فاتت التطبيق اتقفل لما اشتغل على الـ NPU. Attune رجع للمعالج؛ تقدر تجرّب تاني من المحرك ← السرعة.",
  "Item name": "اسم الصنف",
