  "Too heavy for a phone — it can close the app. Core or Blaze run smoothly here; this one is in the desktop app.": "تقيل على الموبايل وممكن يقفل التطبيق. Core أو Blaze بيشتغلوا هنا بسلاسة؛ ده مكانه تطبيق الكمبيوتر.",
