  "No missions yet. Start one above — a saving goal, a weight goal, something to buy, a spending limit, a debt or a course.": "مفيش مهمات لسه. ابدأ واحدة فوق — توفير، وزن، حاجة عايز تشتريها، حد للمصاريف، دين، أو كورس.",
