  "Keep your phone and computer (or two phones) the same. The data is locked before it leaves this device; what you delete on one is deleted on the other, nothing else is lost.": "خلي الموبايل والكمبيوتر (أو موبايلين) زي بعض. البيانات بتتقفل قبل ما تخرج من الجهاز ده؛ اللي تمسحه على واحد بيتمسح على التاني، ومفيش حاجة تانية بتضيع.",
