  "Turn on Notification access for Attune, then come back": "شغّل «الوصول للإشعارات» لـ Attune وارجع",
  "Kept notifications forgotten": "الإشعارات المحفوظة اتمسحت",
  "Find anything… e.g. the wifi password from a screenshot, the address Ahmed sent": "دوّر على أي حاجة… مثلًا باسورد الواي فاي اللي في سكرين، العنوان اللي أحمد بعته",
  "Looking in": "بدوّر في",
  "Nothing found — try other words, or fewer": "ملقتش حاجة — جرّب كلام تاني، أو كلام أقل",
  "Nothing to search yet — add screenshots or keep your notifications below": "لسه مفيش حاجة أدوّر فيها — ضيف سكرينات أو احفظ إشعاراتك تحت",
  "Add screenshots and photos": "ضيف سكرينات وصور",
  "Their text is read on the phone, so “the receipt from Carrefour” finds them. They are kept in Mind.": "الكلام اللي فيها بيتقرا على الموبايل، فـ«فاتورة كارفور» هتلاقيها. وبتتحفظ في العقل.",
  "Keep my notifications for 30 days": "احفظ إشعاراتي 30 يوم",
  "WhatsApp, email, deliveries, banks — so you can find what someone sent. Never SMS. Turning it off forgets them.": "واتساب، إيميل، توصيل، بنوك — عشان تلاقي اللي حد بعته. من غير رسايل SMS أبدًا. ولو قفلتها بتتمسح.",
  "Needs Notification access (the same switch as Money).": "محتاج «الوصول للإشعارات» (نفس اللي بتشغّله للفلوس).",
  "Everything stays on this phone.": "كل حاجة بتفضل على الموبايل ده.",
  "Screenshots & photos": "سكرينات وصور",
  "Notifications": "إشعارات",
  "Saved pages": "صفحات محفوظة",
  "The phone is warm — stopped early so it cools": "الموبايل سخن — وقفت بدري عشان يبرد",
  "Timing {a} of {b}…": "بقيس {a} من {b}…",
  "Fastest on this phone: {g} threads — {t} tokens/s": "الأسرع على الموبايل ده: {g} أنوية — {t} كلمة/ثانية",
  "Couldn't time the model — nothing changed": "مقدرتش أقيس الموديل — مفيش حاجة اتغيرت",
  "Tune for this phone": "ظبّطه على الموبايل ده",
