  "What changed since {d}?": "إيه اللي اتغير من {d}؟",
  "Automations": "أوامر تلقائية",
  "Say what should happen — “when my salary arrives, put 20% in the car fund” — and it runs by itself": "قول عايز إيه يحصل — «لما المرتب ينزل حط 20% في صندوق العربية» — وهو يشتغل لوحده",
  "Say what should happen": "قول عايز إيه يحصل",
  "e.g. When my salary arrives, put 20% in the car fund and tell me": "مثلًا: لما المرتب ينزل حط 20% في صندوق العربية وقولي",
  "I didn't get that as an automation. Try: When my salary arrives, put 20% in the car fund.": "مفهمتش ده كأمر تلقائي. جرّب: لما المرتب ينزل حط 20% في صندوق العربية.",
  "Automation on — it runs on the phone, no AI needed": "الأمر اشتغل — بيشتغل على الموبايل من غير ذكاء اصطناعي",
  "Turn it on": "شغّله",
  "It listens to your bank and wallet notifications (never SMS). When one matches, you get a notification at once and the money goes into the pot.": "بيسمع إشعارات البنك والمحفظة (عمره ما بيقرا الرسايل العادية). لما واحد يطابق، بيجيلك إشعار على طول والفلوس بتدخل الصندوق.",
